sys_script_include.script:
var MSS_Unstructured_Instruction_Utils = Class.create();
MSS_Unstructured_Instruction_Utils.prototype = {
    initialize: function() {},

    //MSSCUSTODY-4383: Create Widget Inbound Record for payload...
    insertInboundWidgetRecord: function(requestData, payload) {
        try {
            var eventsArray = [];
            grWidget = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
            grWidget.initialize();
            grWidget.object_id = requestData.objectid;
            grWidget.object_version = requestData.objectversion;
            grWidget.object_type = requestData.objecttype;
            grWidget.object_id_type = requestData.objectidtype;
            grWidget.event_status = requestData.eventstatus;
            grWidget.setValue('event_date_time', requestData.eventdatetime.replace('T', ' '));
            grWidget.source = requestData.source;
            grWidget.message_id = requestData.messageid;
            grWidget.event_type = requestData.eventtype;
            grWidget.additional_attributes = requestData.additionalattributes;
            grWidget.payload = JSON.stringify(payload);
            var widInbound = grWidget.insert(); //MSSCUSTODY-4383;MSSCUSTODY-4416: Insert Widget Inbound Record
            if (widInbound != '') {

                if (requestData.eventstatus.toUpperCase().indexOf('NEW_CASE') > -1) {
                    // MSSCUSTODY-4383: Trigger event to create case for inbound record.
                    gs.eventQueue('x_hsb11_mss_unst_0.create_unstr_instr_ca', current, widInbound.toString());
                    eventsArray.push({ // MSSCUSTODY-4383: Push Status 200 when processed successfully
                        'Status': '200',
                    });
                    //MSSCUSTODY-6109-update Mixed Instructions Cases via Inbound record.
                } else if (requestData.eventstatus.toUpperCase().indexOf('HIERARCHY_DATA_UPDATE_COMPLETED') > -1) {
                    gs.eventQueue('x_hsb11_mss_unst_0.update_mixed_instr_ca', current, widInbound.toString());
                    eventsArray.push({ //  //MSSCUSTODY-6109: Push Status 200 when processed successfully
                        'Status': '200',
                    });
                } else {
                    //MSSCUSTODY-4416 Create Case Task via Inbound integration | SWB | EL
                    gs.eventQueue('x_hsb11_mss_unst_0.cr_un_in_ca_ta', current, widInbound.toString());
                    eventsArray.push({ // MSSCUSTODY-4416: Push Status 200 when processed successfully
                        'Status': '200',
                    });
                }

                return eventsArray;
            }
            /* grWidget.addQuery('source', grWidget.Source);
             grWidget.query();
             if (grWidget.next()) {
                 eventsArray.push({
                     'Status': '200',
                 });

             }
             return eventsArray;*/
        } catch (e) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils:- Unknown exception while processing Widget Inbound Request ' + e.message);
        }
    },

    //MSSCUSTODY-4383: Create Instruction Case record for Widget Inbound Record.
    insertInstructionCase: function(inboundSysID) {
        try {
            var grInbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
            grInbound.addQuery('sys_id', inboundSysID);
            grInbound.query(); // MSSCUSTODY-4383: Query for inbound event
            if (grInbound.next()) {
                var grInstructionCase = new GlideRecord('x_hsb11_mss_unst_0_instructions_case');
                grInstructionCase.initialize();
                grInstructionCase.u_message_id = grInbound.message_id;
                grInstructionCase.u_source = grInbound.source;
                grInstructionCase.u_event_type = grInbound.event_type;
                grInstructionCase.event_status = grInbound.event_status;
                grInstructionCase.event_date_time = grInbound.event_date_time;
                grInstructionCase.u_object_type = grInbound.object_type;
                grInstructionCase.u_objectidtype = grInbound.object_id_type;
                grInstructionCase.u_objectid = grInbound.object_id;
                grInstructionCase.u_objectversion = grInbound.object_version;
                grInstructionCase.state = 1;
                // grInstructionCase.status = 'Open';
                grInstructionCase.task_status = 'PENDING_PREPROCESSING'; // MSSCUSTODY-5708
                // grInstructionCase.task_status = 'Pending Preprocessing';
                var payload = JSON.parse(grInbound.payload.toString());
                grInstructionCase.source_type = payload.SourceType;
                grInstructionCase.external_line_no = payload.ExternalLineNo;
                grInstructionCase.owning_business = this._updateOwningBusiness(payload.SourceType, this.readPayloadattribute(payload?.ExternalLineNo), this.readPayloadattribute(payload?.ReceiverBIC)); //MSSCUSTODY-6102
                grInstructionCase.instruction_type = this._updateInstructionType(payload.SourceType, this.readPayloadattribute(payload?.ExternalLineNo), this.readPayloadattribute(payload?.ReceiverBIC));
                grInstructionCase.username = payload.UserName;
                grInstructionCase.duration_of_call = payload.DurationOfCall;
                grInstructionCase.number_of_pages = payload.NumberOfPages;
                grInstructionCase.error_codes = payload.ErrorCodes;
                grInstructionCase.transaction_id = payload.TransactionId;
                grInstructionCase.date_time_of_call = payload.DateTimeOfCall;
                if (grInbound.event_status == 'NEW_CASE.SWIFT') { //MSSCUSTODY-6102
                    grInstructionCase.senderbic = payload.SenderBIC;
                    grInstructionCase.receiverbic = payload.ReceiverBIC;
                }
                if (grInbound.event_status == 'NEW_CASE.FAIL') { // MSSCUSTODY-4442: Populate additional fields when event status is NEW_CASE.FAIL
                    grInstructionCase.error_message = payload.ErrorMessage;
                    grInstructionCase.source_file_url = payload.SourceFileUrl;
                }
                grInstructionCase.insert(); // MSSCUSTODY-4383: Insert Instruction Case Record
            }
        } catch (e) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils:- Unknown exception while creating case from widget inbound record ' + e.message);
        }
    },

    //MSSCUSTODY-4416: Create Case Task via Inbound integration | SWB | EL
    insertInstructionCaseTask: function(inboundSysID) {
        try {
            var grInbound = new GlideRecordSecure('x_hsb11_hsbc_mss_o_mss_widget_inbound');
            grInbound.addQuery('sys_id', inboundSysID);
            grInbound.query(); // MSSCUSTODY-4383: Query for inbound event
            if (grInbound.next()) {
                var client_region = '';
                var sender_bic = ''; //8494
                var index_queue = '';
                var case_status = '';
                var grInstructionCaseTask = new GlideRecordSecure('x_hsb11_mss_unst_0_instructions_case_task');
                //  grInstructionCaseTask.initialize();
                grInstructionCaseTask.addQuery('instruction_case.u_objectid', grInbound.object_id);
                grInstructionCaseTask.addActiveQuery();
                grInstructionCaseTask.addEncodedQuery('task_typeNOT INInstruction,Maker ITM,Checker ITM,trade_cancellation_maker,trade_cancellation_checker'); //MSSCUSTODY-7169
                grInstructionCaseTask.query();

                if (grInstructionCaseTask.next()) {
                    var event_status = grInbound.event_status;
                    var payload = JSON.parse(grInbound.payload.toString());

                    //if the mandatory filed bank how to handle or ignore 
                    // grInstructionCaseTask.state = 3;
                    grInstructionCaseTask.event_status = event_status;

                    if (event_status.toUpperCase().indexOf('PREPROCESSING') > -1) {
                        grInstructionCaseTask.source_file_url = this.readPayloadattribute(payload?.SourceFileUrl);
                        grInstructionCaseTask.indexing_ui_url = this.readPayloadattribute(payload?.IndexingUiUrl);
                        grInstructionCaseTask.signature_ui_url = this.readPayloadattribute(payload?.SignatureUiUrl);
                        grInstructionCaseTask.callback_ui_url = this.readPayloadattribute(payload?.CallbackUiUrl);
                        //MSSCUSTODY-5218 --> Updating value of below fields via inbound integration.
                        grInstructionCaseTask.source_file_ui_url = this.readPayloadattribute(payload?.SourceFileUiUrl);
                        grInstructionCaseTask.error_details = this.readPayloadattribute(payload?.ErrorMessage);
                        grInstructionCaseTask.source_file_id = this.readPayloadattribute(payload?.SourceFileId);


                        // MSSCUSTODY-5317 --> Updating Signature Verification and Signature Comment in Indexing itself.
                    } else if (event_status.toUpperCase().indexOf('INDEXING') > -1) {
                        client_region = this.readPayloadattribute(payload?.ClientRegion);
                        sender_bic = this.readPayloadattribute(payload?.SenderBIC); //8494
                        grInstructionCaseTask.operator_id = this.readPayloadattribute(payload?.OperatorID);
                        grInstructionCaseTask.client_name = this.readPayloadattribute(payload?.ClientName); //MSSCUSTODY-7341
                        grInstructionCaseTask.in_scope = this.readPayloadattribute(payload?.InScope);
                        grInstructionCaseTask.index_comment = this.readPayloadattribute(payload?.IndexingComment);
                        index_queue = this.readPayloadattribute(payload?.InstructionType);
                        grInstructionCaseTask.comments = this.readPayloadattribute(payload?.Comment);
                        grInstructionCaseTask.signature_verified = this.readPayloadattribute(payload?.SignatureVerified);
                        grInstructionCaseTask.signature_comment = this.readPayloadattribute(payload?.SignatureComment);
                        if (((event_status.toUpperCase() == 'INDEXING_COMPLETED.IN_SCOPE') && (payload?.SignatureVerified == true)) || (event_status.toUpperCase() == 'INDEXING_COMPLETED.INPROGRESS')) {
                            var types = this.readPayloadattribute(payload?.SelectedUIInstructionTypes);
                            if (types.split(',').length > 1) { // MSSCUSTODY-5970
                                grInstructionCaseTask.setValue('index_queue_multiple', types);
                                if (!(event_status.toUpperCase() == 'INDEXING_COMPLETED.INPROGRESS')) {
                                    this.insertChildCase(grInstructionCaseTask.instruction_case, payload?.HierarchyData.Children, inboundSysID);
                                }
                            }
                        }
                        if (this.readPayloadattribute(payload?.AdditionalData) != '') { //MSSCUSTODY-7031
                            var input = payload?.AdditionalData;
                            for (let i = 0; i < input.length; i++) {
                                if (input[i].name == 'Balance Verification') {
                                    grInstructionCaseTask.balance_verification = input[i].data.status;
                                    grInstructionCaseTask.balance_comment = input[i].data.comment;
                                } else if (input[i].name == 'Cash Forecasting Input') {
                                    grInstructionCaseTask.cash_forecasting_input = input[i].data.status;
                                    grInstructionCaseTask.cash_comment = input[i].data.comment;
                                }
                            }
                        }

                    } else if (event_status.toUpperCase().indexOf('CASE_FORWARDED') > -1) {
                        if (event_status.toUpperCase() == 'CASE_FORWARDED.FAIL') {
                            grInstructionCaseTask.error_details = this.readPayloadattribute(payload?.ErrorMessage);
                        } else if (event_status.toUpperCase() == 'CASE_FORWARDED.SUCCESS') {
                            case_status = '3';
                        }

                    } else if (event_status.toUpperCase().indexOf('CALLBACK_VERIFICATION') > -1) {
                        grInstructionCaseTask.operator_id = this.readPayloadattribute(payload?.OperatorID);
                        grInstructionCaseTask.callback_verified = this.readPayloadattribute(payload?.CallbackVerified);
                        grInstructionCaseTask.callback_option_comment = this.readPayloadattribute(payload?.Comment);

                    } else if (event_status.toUpperCase().indexOf('EXTRACTION') > -1) {
                        grInstructionCaseTask.checker_url_1 = this.readPayloadattribute(payload?.Checker1Url);
                        grInstructionCaseTask.checker_url_2 = this.readPayloadattribute(payload?.Checker2Url);
                        if (event_status.toUpperCase() == 'EXTRACTION_COMPLETED.FAIL') {
                            // MSSCUSTODY-5148
                            grInstructionCaseTask.error_details = this.readPayloadattribute(payload?.ErrorMessage);
                            // case_status = 'Close Complete';
                        } else if (event_status.toUpperCase() == 'EXTRACTION_COMPLETED.SUCCESS') {
                            let status = '';
                            grInstructionCaseTask.data = this.readPayloadattribute(JSON.stringify(payload?.PredicatedData));
                            //MSSCUSTODY-6400
                            status = this.processDataToTasks(grInstructionCaseTask.instruction_case, payload?.PredicatedData, event_status);
                            if (status == 'INSTRUCTIONS.FAILED')
                                event_status = status;
                        }

                    } else if (event_status.toUpperCase().indexOf('REVIEW_COMPLETED.AMEND') > -1 || event_status.toUpperCase().indexOf('REVIEW_COMPLETED.REJECT') > -1 || event_status.toUpperCase().indexOf('REVIEW_COMPLETED.INPROGRESS') > -1) {
                        grInstructionCaseTask.operator_id = this.readPayloadattribute(payload?.OperatorID);
                        grInstructionCaseTask.description = this.readPayloadattribute(payload?.Comment);
                        if ((event_status.toUpperCase() == 'REVIEW_COMPLETED.AMEND') || (event_status.toUpperCase() == 'REVIEW_COMPLETED.INPROGRESS')) { //MSSCUSTODY-7015
                            // MSSCUSTODY-6939 
                            this.deactivateExistingInstructions(grInstructionCaseTask.instruction_case); //MSSCUSTODY-6395
                            let status = '';
                            grInstructionCaseTask.data = this.readPayloadattribute(JSON.stringify(payload?.Data));
                            //MSSCUSTODY-6400
                            status = this.processDataToTasks(grInstructionCaseTask.instruction_case, payload?.Data, event_status);
                            if (status == 'INSTRUCTIONS.FAILED')
                                event_status = status;
                        } //MSSCUSTODY-6276
                    } else if (event_status.toUpperCase().indexOf('REVIEW_COMPLETED.APPROVE') > -1) {
                        grInstructionCaseTask.operator_id = this.readPayloadattribute(payload?.OperatorID);
                        grInstructionCaseTask.data = this.readPayloadattribute(JSON.stringify(payload?.Data));
                        this.deactivateCANCInstructions(grInstructionCaseTask.instruction_case); //MSSCUSTODY-8462
                        //MSSCUSTODY-4549  MSSCUSTODY-5472
                        //MSSCUSTODY-6939     status = this.processDataToTasks(grInstructionCaseTask.instruction_case, payload?.Data, event_status);                      
                    } else if (event_status.toUpperCase().indexOf('CALLBACK_DATA_UPDATE_COMPLETED') > -1) {
                        if (event_status.toUpperCase() == 'CALLBACK_DATA_UPDATE_COMPLETED.SUCCESS') {
                            grInstructionCaseTask.callback_ui_url = this.readPayloadattribute(payload?.CallbackUiUrl);
                        }
                        if (event_status.toUpperCase() == 'CALLBACK_DATA_UPDATE_COMPLETED.FAIL') {
                            grInstructionCaseTask.error_details = this.readPayloadattribute(payload?.ErrorMessage);
                        }
                    }

                    if (!((event_status.toUpperCase() == 'INDEXING_COMPLETED.OUT_OF_SCOPE') || (event_status.toUpperCase() == 'CALLBACK_VERIFICATION_COMPLETED.INPROGRESS') || (event_status.toUpperCase() == 'INDEXING_COMPLETED.INPROGRESS') || (event_status.toUpperCase() == 'REVIEW_COMPLETED.INPROGRESS') || (event_status.toUpperCase() == 'REVIEW_COMPLETED.DISCARD'))) { //MSSCUSTODY-7015 MSSCUSTODY-7330
                        grInstructionCaseTask.state = 3;
                    } else {
                        var processTime = new GlideDateTime;
                        processTime.addSeconds(720); //MSSCUSTODY-5529
                        gs.eventQueueScheduled('x_hsb11_mss_unst_0.updateOnTask', grInstructionCaseTask, grInstructionCaseTask.sys_id, '', processTime);
                        grInstructionCaseTask.work_start = new GlideDateTime().getDisplayValue();
                    }
                    grInstructionCaseTask.update(); // MSSCUSTODY-4383: update Instruction Case task Record

                    //Update case information 
                    if (!(event_status.toUpperCase().indexOf('CALLBACK_DATA_UPDATE_COMPLETED') > -1))
                        this.updateCase(grInstructionCaseTask.instruction_case, event_status, case_status, index_queue, client_region, sender_bic);
                    // if update fail how handle the flow will be stuck.
                } else {
                    gs.info('Script Include - MSS_Unstructured_Instruction_Utils: - cannot find the case from the header objectID');
                }



            }
        } catch (e) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils:- Unknown exception while creating case task from widget inbound record ' + e.message);
        }
    },

    //MSSCUSTODY-6395
    deactivateExistingInstructions: function(caseId) {
        var grInstructionTask = new GlideRecord('x_hsb11_mss_unst_0_instructions_case_task');
        grInstructionTask.addEncodedQuery('task_type=Instruction^instruction_case=' + caseId);
        grInstructionTask.query();
        while (grInstructionTask.next()) {
            grInstructionTask.setValue('state', 4);
            grInstructionTask.update();
        }

    },

    updateMixedInstructionCases: function(inboundSysID) { //MSSCUSTODY-6109
        var grInbound = new GlideRecordSecure('x_hsb11_hsbc_mss_o_mss_widget_inbound');
        grInbound.addQuery('sys_id', inboundSysID);
        grInbound.query();
        if (grInbound.next()) {
            var payload = JSON.parse(grInbound.payload.toString());
            var objectid = grInbound.object_id;
            var grCase = new GlideRecord('x_hsb11_mss_unst_0_instructions_case');
            grCase.addEncodedQuery('parent.ref_sn_bom_case.u_objectid=' + objectid + '^ORu_objectid=' + objectid);
            grCase.query();
            while (grCase.next()) {
                grCase.error_message = this.readPayloadattribute(payload?.ErrorMessage);
                grCase.task_status = grInbound.event_status;
                grCase.update();
            }
        }
    },

    insertChildCase: function(caseId, children, inboundSysID) {
        var data = [];
        // MSSCUSTODY-5970
        var grInbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
        grInbound.addQuery('sys_id', inboundSysID);
        grInbound.query(); // MSSCUSTODY-5970
        if (grInbound.next()) {
            var parentCase = new GlideRecord('x_hsb11_mss_unst_0_instructions_case');
            if (parentCase.get(caseId)) {
                for (var i = 0; i < children.length; i++) {
                    try {
                        let newCase = null;
                        var grInstructionCase = new GlideRecord('x_hsb11_mss_unst_0_instructions_case');
                        grInstructionCase.initialize();
                        grInstructionCase.parent = caseId;
                        grInstructionCase.source_type = parentCase.source_type;
                        grInstructionCase.external_line_no = parentCase.external_line_no;
                        grInstructionCase.owning_business = parentCase.owning_business;
                        grInstructionCase.date_time_of_call = parentCase.date_time_of_call;
                        grInstructionCase.transaction_id = parentCase.transaction_id;
                        grInstructionCase.username = parentCase.username;
                        grInstructionCase.duration_of_call = parentCase.duration_of_call;
                        grInstructionCase.number_of_pages = parentCase.number_of_pages;
                        grInstructionCase.error_codes = parentCase.error_codes;
                        grInstructionCase.senderbic = parentCase.senderbic;
                        grInstructionCase.receiverbic = parentCase.receiverbic;
                        grInstructionCase.u_message_id = grInbound.message_id;
                        grInstructionCase.u_source = grInbound.source;
                        grInstructionCase.u_event_type = grInbound.event_type;
                        grInstructionCase.task_status = grInbound.event_status;
                        grInstructionCase.event_date_time = grInbound.event_date_time;
                        grInstructionCase.u_object_type = grInbound.object_type;
                        grInstructionCase.u_objectidtype = grInbound.object_id_type;
                        grInstructionCase.u_objectversion = grInbound.object_version;
                        grInstructionCase.state = 1;
                        grInstructionCase.instruction_type = this.readPayloadattribute(children[i]?.['InstructionType']);
                        grInstructionCase.u_objectid = this.readPayloadattribute(children[i]?.['SwbID']);
                        newCase = grInstructionCase.insert();
                        if (newCase != "") { //MSSCUSTODY-6109
                            var requestBody = {};
                            requestBody.SwbID = grInstructionCase.getValue('u_objectid');
                            requestBody.InstructionType = grInstructionCase.getValue('instruction_type');
                            requestBody.CaseID = grInstructionCase.getValue('number');
                            requestBody.SysID = grInstructionCase.getValue('sys_id');
                        }
                        data.push(requestBody);
                    } catch (e) {
                        gs.info('Script Include - MSS_Unstructured_Instruction_Utils:- Unknown exception while creating case ' + e.message);
                    }
                }
                //MSSCUSTODY-6109
                var jsonObj = {};
                jsonObj.Parent = {
                    "SwbID": parentCase.getValue('u_objectid'),
                    "InstructionType": parentCase.getValue('instruction_type'),
                    "CaseID": parentCase.getValue('number'),
                    "SysID": parentCase.getValue('sys_id')
                };
                jsonObj.Children = data;
                var body = {};
                body.HierarchyData = jsonObj;
                //MSSCUSTODY-6109
                var record = new GlideRecord("x_hsb11_hsbcmss_sw_hsbc_swb_outbound_table");
                record.initialize();
                var uuid = gs.generateGUID();
                var formattedUuid = uuid.substring(0, 8) + '-' + uuid.substring(8, 12) + '-' + uuid.substring(12, 16) + '-' + uuid.substring(16, 20) + '-' + uuid.substring(20);
                record.u_message_id = formattedUuid;
                record.reference_id = parentCase.sys_id.toString();
                record.payload_version = parentCase.payload_version;
                record.state = 'Ready to be sent';
                record.instruction_type = parentCase.instruction_type;
                record.source_system = 'iQube';
                record.owningbusiness = parentCase.owning_business;
                record.process = 'SMARTWORKBENCH_UNSTRUCTURED_INSTRUCTIONS';
                record.swb_id = parentCase.u_objectid.toString();
                record.request_body = JSON.stringify(body);
                record.process_status = 'UPDATE_HIERARCHY_DATA';
                record.insert();
            }
        }
    },

    //8269
    clientname: function(caseId) {
        if (!caseId) {
            return '';
        }
        var caseRecord = new GlideRecord('x_hsb11_mss_unst_0_instructions_case');
        if (caseRecord.get(caseId)) {

            var parentCase = caseRecord.getValue('parent') || caseId;

            var parentCaseRecord = new GlideRecord('x_hsb11_mss_unst_0_instructions_case');
            if (parentCaseRecord.get(parentCase)) {

                var grTaskRecord = new GlideRecord('x_hsb11_mss_unst_0_instructions_case_task');
                grTaskRecord.addQuery('instruction_case', parentCase);
                grTaskRecord.addQuery('task_type', 'indexing');
                grTaskRecord.query();

                if (grTaskRecord.next()) {
                    return grTaskRecord.getValue('client_name');
                }
            }
        }
        return '';
    },
    //8269 end


    /*
     * read the payload attribute
     */
    readPayloadattribute: function(value) {
        let return_value = '';
        if (value != undefined) {
            return_value = value;
        }
        return return_value;
    },

    convertToUpperCase: function(value) { //MSSCUSTODY-7841
        let return_value = '';
        if (value != undefined) {
            return_value = value.toUpperCase();
        }
        return return_value;
    },
    /*
     *	update case information
     */
    updateCase: function(caseID, event_status, case_status, index_queue, client_region, sender_bic) {
        var updatesysID = null;
        var grInstructionCase = new GlideRecord('x_hsb11_mss_unst_0_instructions_case');
        grInstructionCase.initialize();
        if (grInstructionCase.get(caseID)) {
            grInstructionCase.setValue('task_status', event_status);
            if (!gs.nil(case_status)) {
                grInstructionCase.setValue('state', case_status);
            }
            if (!gs.nil(index_queue)) {
                grInstructionCase.setValue('instruction_type', index_queue);
            }
            if (!gs.nil(client_region)) {
                grInstructionCase.setValue('legal_entity', client_region);
            }
            if (!gs.nil(sender_bic)) {
                grInstructionCase.setValue('senderbic', sender_bic); //8494
            }
            updatesysID = grInstructionCase.update();
        } else {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils: - cannot find the case from the header objectID');
        }

        return updatesysID;
    },

    /*
     * Review Approved Data handling
     * MSSCUSTODY-4549
     */
    //MSSCUSTODY-5471,5472,5914
    processDataToTasks: function(caseId, data, event_status) {
        if (data == undefined) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils: - Review Approve Data is undefined, caseID:' + caseId);
        }
        let count = 0;
        for (let i = 0; i < data.length; i++) {

            let paymentType = this.readPayloadattribute(data[i]?.["OutputMessageType"]);
            let grInstructionCaseTask = new GlideRecordSecure('x_hsb11_mss_unst_0_instructions_case_task');
            grInstructionCaseTask.initialize();
            var currency, inputCurrency;
            if (paymentType == 'MT380') {
                //MT380
                grInstructionCaseTask.senders_reference = this.readPayloadattribute(data[i]?.["Sender's Reference"]);
                grInstructionCaseTask.action = this.readPayloadattribute(data[i]?.["Action"]);
                grInstructionCaseTask.credit_account_number = this.readPayloadattribute(data[i]?.["Credit Account Number"]);
                grInstructionCaseTask.debit_account_number = this.readPayloadattribute(data[i]?.["Debit Account Number"]);
                grInstructionCaseTask.on_behalf_of = this.readPayloadattribute(data[i]?.["On Behalf of"]);
                grInstructionCaseTask.details_of_deal = this.readPayloadattribute(data[i]?.["Details of Deal"]);
                grInstructionCaseTask.fx_direction = this.readPayloadattribute(data[i]?.["FX Direction"]);
                var baseCurrency = this.readPayloadattribute(data[i]?.["Base Currency"]); //6253
                grInstructionCaseTask.currency = this.setCurrency(this.readPayloadattribute(data[i]?.["Base Currency"])); //6253 //7972
                grInstructionCaseTask.counter_currency = this.setCurrency(this.readPayloadattribute(data[i]?.["Counter Currency"])); //7972
                inputCurrency = this.readPayloadattribute(data[i]?.["Base Currency"]).trim();
                let inputAmount = this.readPayloadattribute(data[i]?.["Amount"]).trim();
                inputAmount = inputAmount.replace(/[^0-9.]/g, ''); //MSSCUSTODY-7226
                if (inputCurrency != "") {
                    let convertedAmount = this.ConvertToUSD(inputCurrency, inputAmount);
