    getAbbreviation: function(fullName) {
        //MSSCUSTODY-7714
        switch (fullName) {
            case 'BIC Code':
                return 'BIC Code';
            case 'Name and address':
                return 'Name and address';
            case 'Austrian Bankleitzahl':
                return 'AT';
            case 'Australian BSB Code':
                return 'AU';
            case 'German Bankleitzahl':
                return 'BL';
            case 'Canadian Payment Routing code':
                return 'CC';
            case 'CHIPS ID':
                return 'CH';
            case 'CHIPS Participant Identifier':
                return 'CP';
            case 'Spanish Interbanking code':
                return 'ES';
            case 'Fed Wire code':
                return 'FW';
            case 'HEBIC':
                return 'GR';
            case 'Hong Kong Clearing code':
                return 'HK';
            case 'Indian Financial System Code':
                return 'IN';
            case 'Italian Identification code':
                return 'IT';
            case 'New Zealand Clearing code':
                return 'NZ';
            case 'Polish Clearing code':
                return 'PL';
            case 'Portuguese Clearing code':
                return 'PT';
            case 'Russian Central Bank Id code':
                return 'RU';
            case 'UK Sort Code':
                return 'SC';
            case 'Swiss Clearing code (BC code)':
                return 'SW';
            case 'South African Clearing code':
                return 'ZA';
            default:
                return '';
        }
    },

    getFormattedName: function(name) {
        //MSSCUSTODY-7790
        if (!name) {
            return '';
        }
        return name.length > 35 ? name.substring(0, 35) : name;
    },

    getFormattedAddress: function(name, address) {
        //MSSCUSTODY-7790
        if (!address) {
            address = '';
        }

        var prefix = '';
        if (name && name.length > 35) {
            prefix = name.substring(35);
        }

        var finalAddress = (prefix + address).trim();
        finalAddress = this.addChar(finalAddress, 35);
        return finalAddress;
    },

    addChar: function(str, interval) {
        if (!str) {
            return '';
        }
        return str.match(new RegExp('.{1,' + interval + '}', 'g')).join('|');
    },

    getCallbackValue: function(caseID, outputmessagetype, amount, basecurrency, currency) {
        //MSSCUSTODY-6253 
        try {
            var callbackflag = 'false'; // Default value

            var grcase = new GlideRecord("x_hsb11_mss_unst_0_instructions_case");
            if (grcase.get(caseID)) {
                var owningBusiness = grcase.getValue('owning_business');
                var sourceType = grcase.getValue('source_type');
                var sett = grcase.getValue('instruction_type');
            }
            // Query the threshold table
            var tsh = new GlideRecord('x_hsb11_mss_unst_0_business_region_threshold');
            tsh.addEncodedQuery('owning_business=' + owningBusiness + '^source_type=' + sourceType + '^instruction_type=' + sett + '^outputmessagetype=' + outputmessagetype + '^callback_flag=true');
            tsh.query();
            if (tsh.next()) {
                var thrValue = Number(tsh.getValue('criteria'));
                var inputCurrency = (outputmessagetype === "MT380") ? basecurrency : currency;

                if (outputmessagetype === "MT542") {
                    callbackflag = 'true';
                } else if (inputCurrency.trim() && amount) {
                    var convertedAmount = this.ConvertToUSD(inputCurrency, amount);
                    callbackflag = convertedAmount > thrValue ? 'true' : 'false';
                }
            }
            return callbackflag;
        } catch (e) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils: getCallbackValue- Unknown exception while returning CallbackFlag  ' + e.message);
        }
    },

    getHighValue: function(caseID, outputmessagetype, amount, basecurrency, currency) {
        //MSSCUSTODY-6081
        try {
            var isHighValue = 'No';
            var inputCurrency, inputAmount, convertedAmount, thrValue;

            var grcase = new GlideRecord("x_hsb11_mss_unst_0_instructions_case");
            if (grcase.get(caseID)) {
                var owningBusiness = grcase.getValue('owning_business');
                var instructionType = grcase.getValue('instruction_type');
            }
            var tsh = new GlideRecord('x_hsb11_mss_unst_0_business_region_threshold');
            tsh.addEncodedQuery('owning_business=' + owningBusiness + '^instruction_type=' + instructionType + '^outputmessagetype=' + outputmessagetype + '^hv_flag=true');
            tsh.query();

            if (tsh.next()) {
                thrValue = Number(tsh.getValue('hv_threshold_usd'));
                inputCurrency = (outputmessagetype === "MT380") ? basecurrency : currency;
                if (inputCurrency.trim() && amount) {
                    convertedAmount = this.ConvertToUSD(inputCurrency, amount);
                } else {
                    convertedAmount = 0;
                }

                if (convertedAmount > thrValue) {
                    isHighValue = 'Yes';
                } else {
                    isHighValue = 'No';
                }
            }
            return isHighValue;
        } catch (e) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils: getHighValue- Unknown exception while returning HighValue  ' + e.message);
        }

    },


    updateCallbackTask: function(caseId) {
        var gTask = new GlideRecord('x_hsb11_mss_unst_0_instructions_case_task');
        gTask.addQuery('instruction_case', caseId);
        gTask.addQuery('task_type', 'Instruction');
        gTask.addActiveQuery();
        gTask.query();
        var row = gTask.getRowCount();
        var count = 0;
        while (gTask.next()) {
            if (gTask.outputmessagetype == "MT599") {
                count++;
            } else if (gTask.callback_verification_required == 'false') {
                count++;
            }
        }
        if (row != count) {
            return true;
        } else {
            return false;
        }
    },

    //MSSCUSTODY-7972:Currency visibility
    setCurrency: function(curr) {
        try {
            if (!curr) {
                gs.info('Currency is empty in payload');
                return;
            }
            var fxCurr = new GlideRecord('fx_currency');
            fxCurr.addQuery('code', curr);
            fxCurr.query();
            if (fxCurr.next()) {
                return fxCurr.sys_id;
            } else {
                gs.info('Currency not found in fx_currency');
            }
        } catch (e) {
            gs.error('Error in setCurrency: ' + e.message);
        }
    },

    //MSSCUSTODY-5471
    ConvertToUSD: function(inputCurrency, inputAmount) {
        try { //MSSCUSTODY-7972
            var conv = new sn_currency.GlideCurrencyConverter(inputCurrency, 'USD');
            conv.setAmount(inputAmount);
            var convertValues = conv.convert();
            var convertedAmount = convertValues.getAmount();
            return convertedAmount;
        } catch (e) {
            return '';
        }
    },

    /*
     * Convert the yyyymmdd to Date
     */
    stringConvertToDate: function(dateString) {
        // Extract year, month, and day
        let year = dateString.substring(0, 4);
        let month = dateString.substring(4, 6);
        let day = dateString.substring(6, 8);

        // Create a new Date object
        // Note: JavaScript months are zero-based, so subtract 1 from the month
        let dtstr = year + '-' + month + '-' + day;
        let valuedate = new GlideDateTime(dtstr);
        return valuedate;
    },

    //MSSCUSTODY-5148 validating loggedin user's role
    isMember: function() {
        var grmember = new GlideRecord('sys_user_grmember');
        grmember.addEncodedQuery('group.sys_idIN' + gs.getProperty('x_hsb11_mss_unst_0.Unstructured_structured_Groups'));
        grmember.addQuery('user', gs.getUserID());
        grmember.query();
        if (grmember.next()) {
            return true;
        } else {
            return false;
        }

    },

    sendMessage: function(SysID) {
        try {
            var gr = new GlideRecord('x_hsb11_hsbcmss_sw_hsbc_swb_outbound_table');
            gr.get(SysID);
            gr.query();
            while (gr.next()) {
                var status = gr.getValue('process_status');
                var swbToken = gs.getProperty('x_hsb11_hsbcmss_sw.hsbcmss_swb_api_token');
                var message = gr.getValue('u_message_id');
                var swb = gr.getValue('swb_id');
                var business = gr.getValue('owningbusiness');
                var caseId = gr.getValue('reference_id');
                var url = gr.getValue('callback_url');
                var type = gr.getValue('instruction_type');
                var gdt = new GlideDateTime();
                var dateTimeString = gdt.getDisplayValueInternal().split(" ");
                var date = dateTimeString[0];
                var time = dateTimeString[1];
                var milliseconds = gdt.getNumericValue() % 1000;
                var formattedDate = date + "T" + time + "." + milliseconds.toString().padStart(3, '0') + "Z";

                var r = new sn_ws.RESTMessageV2('x_hsb11_hsbcmss_sw.HSBC SWB API', 'Send Task Details ');
                r.setStringParameterNoEscape('swb_token', swbToken);


                if (status == 'TRIGGER_PREPROCESSING') {
                    var grCaseRecord = new GlideRecord('x_hsb11_mss_unst_0_instructions_case');
                    grCaseRecord.get(caseId);
                    grCaseRecord.query();
                    if (grCaseRecord.next()) {
                        var external_no = grCaseRecord.getValue('external_line_no');
                        var ar = new GlideRecord('x_hsb11_mss_unst_0_mss_external_line_number_mapping');
                        ar.addQuery('external_line_number', external_no);
                        ar.query();
                        if (ar.next()) {
                            var workType = ar.getValue('work_type');
                            var section = ar.getValue('section');
                            var dept = ar.getValue('department');
                        }
                    }
                    var body = {
                        "Header": {
                            "MessageID": message,
                            "SwbID": swb,
                            "SourceSystem": "iQube",
                            "Process": "SMARTWORKBENCH_UNSTRUCTURED_INSTRUCTIONS",
                            "ProcessStatus": status,
                            "OperationTime": formattedDate,
                            "ReferenceID": caseId,
                            "PayloadVersion": "1",
                            "CallBackUrl": url
                        },
                        "Payload": {
                            "OwningBusiness": business,
                            "InstructionType": type,
                            "WorkType": workType,
                            "Section": section,
                            "Dept": dept
                        }
                    };
                } else if (status == 'TRIGGER_CASE_FORWARD') {
                    var body = {
                        "Header": {
                            "MessageID": message,
                            "SwbID": swb,
                            "SourceSystem": "iQube",
                            "Process": "SMARTWORKBENCH_UNSTRUCTURED_INSTRUCTIONS",
                            "ProcessStatus": status,
                            "OperationTime": formattedDate,
                            "ReferenceID": caseId,
                            "PayloadVersion": "1",
                            "CallBackUrl": url
                        },
                        "Payload": {
                            "Receiver": ""
                        }
                    };

                } else if (status == 'TRIGGER_EXTRACTION') {
                    var body = {
                        "Header": {
                            "MessageID": message,
                            "SwbID": swb,
                            "SourceSystem": "iQube",
                            "Process": "SMARTWORKBENCH_UNSTRUCTURED_INSTRUCTIONS",
                            "ProcessStatus": status,
                            "OperationTime": formattedDate,
                            "ReferenceID": caseId,
                            "PayloadVersion": "1",
                            "CallBackUrl": url
                        }
                    };
                } else if (status == 'UPDATE_CALLBACK_DATA' || status == 'UPDATE_HIERARCHY_DATA') {
                    var body = {
                        "Header": {
                            "MessageID": message,
                            "SwbID": swb,
                            "SourceSystem": "iQube",
                            "Process": "SMARTWORKBENCH_UNSTRUCTURED_INSTRUCTIONS",
                            "ProcessStatus": status,
                            "OperationTime": formattedDate,
                            "ReferenceID": caseId,
                            "PayloadVersion": "1",
                        },
                    };
                    body.Payload = JSON.parse(gr.getValue('request_body'));
                } else if (status == 'CLOSE_CASE') {
                    var body = {
                        "Header": {
                            "MessageID": message,
                            "SwbID": swb,
                            "SourceSystem": "iQube",
                            "Process": "SMARTWORKBENCH_UNSTRUCTURED_INSTRUCTIONS",
                            "ProcessStatus": status,
                            "OperationTime": formattedDate,
                            "ReferenceID": caseId,
                            "PayloadVersion": "1",
                            "CallBackUrl": url
                        },
                        "Payload": {
                            "Result": "Success",
                            "Message": " ",
                        }
                    };
                }
                var toSend = JSON.stringify(body);
                r.setRequestBody(toSend);
                gr.state = 'Processing';
                gr.request_date = new GlideDateTime();
                gr.update();
                var response = r.execute();
                var responseBody = response.getBody();
                var httpStatus = response.getStatusCode();
                try {
                    var resp_parsed = JSON.parse(responseBody);
                } catch (err) {
                    gr.error_body = 'Response is coming in HTML format.Unable to Parse';
                    gr.error_code = httpStatus;
                    gr.state = 'Error';
                    gr.response_body = responseBody;
                    gr.update();
                    //response.setStatus(400); 
                    //response.setBody({ "status": "failure", "error": { "message": "Invalid JSON", "detail": err.message } }); 
                    return;
                }


                if (httpStatus == '202' || httpStatus == '200') {

                    gr.response_body = responseBody;
                    gr.response_code = httpStatus;
                    gr.swb_id = resp_parsed.swbId;
                    gr.response_date = new GlideDateTime();
                    gr.state = "Processed";
                } else if (httpStatus == '500' || httpStatus == '504') { //added as part of MSSCUSTODY-4739 Development
                    var count = gr.getValue("counter");
                    if (count < 2) {
                        count++;
                        gr.counter = count;
                        gr.state = "Retrying";
                        var processTime = new GlideDateTime;
                        processTime.addSeconds(300);
                        gs.eventQueueScheduled('x_hsb11_hsbcmss_sw.create_un_in_task_swb', gr, gr.sys_id, '', processTime);
                    } else {
                        gr.response_code = httpStatus;
                        gr.error_body = responseBody;
                        gr.error_code = resp_parsed.status;
                        gr.response_message = response.getErrorMessage();
                        gr.state = 'Error';
                    }
                } else if (httpStatus == '404' || httpStatus == '502') { //added as part of MSSCUSTODY-4739 Development
                    var count = gr.getValue("counter");
                    if (count < 2) {
                        count++;
                        gr.counter = count;
                        gr.state = "Retrying";
                        gs.eventQueue('x_hsb11_hsbcmss_sw.create_un_in_task_swb', gr, gr.sys_id);
                    } else {
                        gr.response_code = httpStatus;
                        gr.error_body = responseBody;
                        gr.error_code = resp_parsed.status;
                        gr.response_message = response.getErrorMessage();
                        gr.state = 'Error';
                    }
                } else {
                    gr.response_code = httpStatus;
                    gr.error_body = responseBody;
                    gr.error_code = resp_parsed.status;
                    gr.response_message = response.getErrorMessage();
                    gr.state = 'Error';

                }
                gr.response_date = new GlideDateTime();
                gr.update();
            }
        } catch (e) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils:- Unknown exception while Sending Task Details to SWB  ' + e.message);
        }
    },

    sendItmInstructions: function(SysID, messagetype) { //MSSCUSTODY-7051
        try {
            var gr = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
            gr.get(SysID); //MSSCUSTODY-7930
            gr.query();
            while (gr.next()) {
                var r = new sn_ws.RESTMessageV2('x_hsb11_mss_tsd.ITM Outbound Api', 'ITM Instruction Outbound');
                r.setStringParameterNoEscape("itm_api_token", gs.getProperty('x_hsb11_mss_tsd.itm_api_token'));
                r.setStringParameterNoEscape("base_itm_endpoint", gs.getProperty('x_hsb11_mss_tsd.itm_base_endpoint'));
                if (messagetype == 'MT103' || messagetype == 'MT202') { //MSSCUSTODY-8301
                    //  r.setStringParameterNoEscape("itm_instruction_api", gs.getProperty('x_hsb11_mss_tsd.itm_instruction_api'));  //8434
                    gs.info("Script Include - MSS_Unstructured_Instruction_Utils:- Record ID =" + SysID + " Endpoint utilized =" + gs.getProperty('x_hsb11_mss_tsd.itm_instruction_api'));
                } else if (messagetype == 'MT380') {
                    r.setStringParameterNoEscape("itm_instruction_api", gs.getProperty('x_hsb11_mss_tsd.itm_instruction_fx_api'));
                    gs.info("Script Include - MSS_Unstructured_Instruction_Utils:- Record ID =" + SysID + " Endpoint utilized =" + gs.getProperty('x_hsb11_mss_tsd.itm_instruction_fx_api'));
                } else if (messagetype == 'MT540' || messagetype == 'MT541' || messagetype == 'MT542' || messagetype == 'MT543') {
                    r.setStringParameterNoEscape("itm_instruction_api", gs.getProperty('x_hsb11_mss_tsd.itm_instruction_trade_api'));
                    gs.info("Script Include - MSS_Unstructured_Instruction_Utils:- Record ID =" + SysID + " Endpoint utilized =" + gs.getProperty('x_hsb11_mss_tsd.itm_instruction_trade_api'));
                }
                var toSend = gr.request_body;
                r.setRequestBody(toSend);
                gr.state = 'Processing';
                gr.request_date = new GlideDateTime();
                gr.update();
                var response = r.execute();
                var responseBody = response.getBody();
                var httpStatus = response.getStatusCode();
                if (httpStatus == '200') {
                    //   this.itmVerification('Pass', gr.document_id, responseBody.message); //MSSCUSTODY-7199
                    gr.response_body = responseBody;
                    gr.state = "Processed";
                } else {
                    if (messagetype == 'MT103' || messagetype == 'MT202') { //8434
                        this.itmVerification('Fail', gr.document_id, 'Cash instruction cannot be processed yet in iQube, Manual handling is required');
                    } //MSSCUSTODY-7199
                    gr.error_body = responseBody;
                    gr.error_code = httpStatus;
                    gr.state = 'Error';
                }
                gr.request_type = 'Post Payload'; //MSSCUSTODY-7199
                gr.response_date = new GlideDateTime();
                gr.update();
            }
        } catch (e) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils:- Unknown exception while Sending Instructions to ITM  ' + e.message);
        }
    },

    itmVerification: function(status, taskID, message) { //MSSCUSTODY-7199
        var grtask = new GlideRecord('x_hsb11_mss_unst_0_instructions_case_task');
        if (grtask.get(taskID)) {
            grtask.itm_verification = status;
            grtask.error_details = message;
            grtask.state = 3;
            grtask.update();
        }
    },

    _updateOwningBusiness: function(sourcetype, extlineno, receiverbic) {

        var recBIC = receiverbic.substring(0, 8);
        var gr = new GlideRecord("x_hsb11_mss_unst_0_mss_external_line_number_mapping");
        sourcetype === 'FAX' ? gr.addQuery('external_line_number', extlineno) : gr.addQuery('receiverbic', 'STARTSWITH', recBIC);
