        }

    },



    getUserAuthDetail: function(user_id, role_name) {
        var url = '',
            gr_usr = new GlideRecord('sys_user');
        gr_usr.addQuery('user_name', 'STARTSWITH', user_id);
        gr_usr.query();
        if (gr_usr.next()) {
            //compare maker with request details
            if (role_name == 'maker') {
                gs.info(role_name);
                url = 'user=' + gr_usr.sys_id + '^group.sys_idIN' + gs.getProperty('x_hsb11_mss_unst_0.Unstructured_structured_Groups'); //7922
            } else if (role_name == 'checker') {
                gs.info(role_name);
                url = 'user=' + gr_usr.sys_id + '^group.sys_idIN' + gs.getProperty('x_hsb11_mss_unst_0.Unstructured_structured_Groups'); //7922
            }

            var gr_ect = new GlideRecord('sys_user_grmember');
            gr_ect.addEncodedQuery(url);
            gr_ect.query();
            // gs.info("BEOFRE LOOP");
            if (gr_ect.next()) {
                gs.info(true);
                return true;
            } else {
                gs.info(false);
                return false;
            }
        } else {
            return 'invalid';
        }
        //return auth;

    },

