                            this.formatSourceDate(grCase.getValue('sys_created_on')) //MSSCUSTODY-7827
                        );
                        break;

                    default:
                        break;
                }

                if (messageJSON) {
                    requestBody = this.itmHeader( //MSSCUSTODY-6747
                        grtask.getValue('sys_id'),
                        grCase.getValue('legal_entity'),
                        grtask.getValue('action'),
                        grtask.getValue('outputmessagetype'),
                        grCase.getValue('owning_business'),
                        grtask.getValue('fx_direction'),
                        messageJSON
                    );
                    var groutbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
                    groutbound.request_body = requestBody;
                    groutbound.state = 'Ready to be sent';
                    /*  groutbound.swb_id = objID;
                    groutbound.u_message_id = messageID;
                    groutbound.source_system = 'iQube';
                    groutbound.instruction_type = indexqueue;
					groutbound.owningbusiness = owningbusiness;
                    groutbound.process = 'ITM VERIFICATION';
                    groutbound.process_status = 'ITM VERIFICATION'; MSSCUSTODY-7051*/
                    groutbound.source_table = 'x_hsb11_mss_unst_0_instructions_case_task';
                    groutbound.document_id = grtask.getValue('sys_id');
                    groutbound.sys_scope = "b208a7c083689e50c6695855eeaad3d2"; //MSSCUSTODY-7930
                    groutbound.request_date = new GlideDateTime();
                    groutbound.insert();
                }
            }
        } catch (e) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils: generateInstructionJSON - Unknown exception while Sending Task Details to ITM  ' + e.message);

        }
    },


    getSecurityType: function(type) { //8435
        switch (type) {
            case 'ISIN':
                return 'ISIN';
            case 'CUSIP':
                return 'US';
            case 'SEDOL':
                return 'GB';
            default:
                return '';
        }
    },


    getTransactionType: function(messageType) { //MSSCUSTODY-7930
        switch (messageType) {
            case 'MT103':
                return 'PAYM';
            case 'MT202':
                return 'PAYM';
            case 'MT380':
                return 'FXRQ';
            case 'MT540':
                return 'RFP';
            case 'MT541':
                return 'RVP';
            case 'MT542':
                return 'DFP';
            case 'MT543':
                return 'DVP';
            default:
                return '';
        }
    },

    getTransactionSubType: function(messageType, fxdirection) { //MSSCUSTODY-7930
        var value = '';
        if (messageType == 'MT103') {
            value = 'CTRF';
        } else if (messageType == 'MT202') {
            value = 'FITRF';
        } else if (messageType == 'MT380') {
            value = fxdirection == 'BUY' ? 'BUYI' : 'SELL';
        }
        return value;
    },


    countryFormat: function(markets) { //MSSCUSTODY-7827
        var value = '';
        if (markets == 'HBEU')
            value = 'UK';
        else if (markets == 'HBFR')
            value = 'FR';

        return value;
    },

    itmHeader: function(taskId, legalEntity, action, messageType, owningBusiness, fxdirection, cmf) { //MSSCUSTODY-6747
        var message = messageType.toString();
        var body = {};
        if (message == "MT103" || message == "MT202" || message == "MT380") {
            body = {
                "instructions": [{
                    "sourceUniqueRef": taskId + '|Unstructured', //Append '|Unstructured' as separator MSSCUSTODY-7930
                    "clientAccountRegion": legalEntity,
                    "instructionType": action,
                    "transactionType": this.getTransactionType(messageType), //MSSCUSTODY-7930
                    "transactionSubType": this.getTransactionSubType(messageType, fxdirection), //MSSCUSTODY-7930
                    "messageCategory": messageType,
                    "productIdentifier": owningBusiness.substring(0, owningBusiness.indexOf(' ')),
                    "countryIdentifier": this.countryFormat(legalEntity), //MSSCUSTODY-7827
                    "payload": cmf
                }]
            };
        } else {
            body = {
                "instructions": [{
                    "sourceUniqueRef": taskId + '|Unstructured', //Append '|Unstructured' as separator MSSCUSTODY-7930
                    "clientAccountRegion": legalEntity,
                    "instructionType": action,
                    "transactionType": "SETT",
                    "transactionSubType": this.getTransactionType(messageType), //MSSCUSTODY-7930
                    "messageCategory": messageType,
                    "productIdentifier": owningBusiness.substring(0, owningBusiness.indexOf(' ')),
                    "countryIdentifier": this.countryFormat(legalEntity), //MSSCUSTODY-7827
                    "payload": cmf
                }]
            };
        }
        return JSON.stringify(body);
    },

    formatDate: function(dateValue) {
        if (dateValue) {
            var gdt = new GlideDateTime(dateValue);
            var formatteddate = gdt.getDate().getByFormat('yyyy-MM-dd');
            return formatteddate;
        }
        return "";
    },


    formatSourceDate: function(dateValue) { //MSSCUSTODY-7827
        if (dateValue) {
            var gdt = new GlideDateTime(dateValue);
            var datePart = gdt.getDate().getByFormat('yyyy-MM-dd');
            var timePart = gdt.getTime().getByFormat('HH:mm:ss.');
            var a = datePart + "T" + timePart + '000+00:00';
            return a;
        }
        return "";
    },

    removeCommas: function(integerString) { //MSSCUSTODY-8387
        if (integerString)
            return integerString.replace(/,/g, '');
        else {
            return '';
        }
    },

