    cashPaymentsMT103: function(source_type, senderbic, senreference, action, valuedate, currency, amount, ordinstitution, ordcustomer, debitaccnum, creditaccnum, creditaccname, sendereceiver, charges, intermediarybank, intermediaryaccnum, accwithinstution, creditaccbic, intermediarybanktype, accwithinstutiontype, creditacctype, intermediarybankaddress, accwithinstutionname, accwithinstutionaddress, creditaccaddress, orderingcustomertype, orderingcustomername, orderingcustomeraddress, intermediarybankcode, orderingcustomerlei, orderinginstitutionlei, intermediarybanklei, accountwithinstitutionlei, creditaccountlei, remittanceinfo, sourceDate, purposecode, purposepayment) {
        try {
            var body = {
                "wrapper": {
                    "transactions": {
                        "sourceCreateDate": sourceDate,
                        "sourceName": source_type, //MSSCUSTODY-6746
                        "clientShortName": source_type === 'FAX' ? "NULL" : senderbic.slice(0, 8) + senderbic.slice(9, senderbic.length), //MSSCUSTODY-6746
                        "trade": {
                            "tradeOrderDetails": {
                                "customerReference": senreference,
                                "customerOrderType": action,
                                "orderValueDate": valuedate,
                                ...(purposecode && {
                                    "orderReason": purposecode
                                }),
                                "orderTransactionDetails": {
                                    "orderAmountDetail": [{
                                            "amountType": "32A",
                                            "amount": amount,
                                            "currencyDetails": {
                                                "currencyCode": currency
                                            }
                                        },
                                        {
                                            "amountType": "33B",
                                            "amount": amount,
                                            "currencyDetails": {
                                                "currencyCode": currency
                                            }
                                        }
                                    ]
                                }
                            },
                            "tradeComments": {
                                "comments": []
                            },
                            // Spread operator to add tradeMarketCharges block here if charges == "BEN" or "SHA" //MSSCUSTODY-5956
                            ...(charges == "BEN" && {
                                "tradeMarketCharges": {
                                    "marketCharge": [{
                                        "chargeType": "71F",
                                        "chargeAmount": "0",
                                        "currencyDetails": {
                                            "currencyCode": 'GBP'
                                        }
                                    }]
                                }
                            }),

                            "partiesInvolved": {
                                "partyRoleDetails": [{
                                    "partyRoleType": "52A",
                                    "partyDetails": {
                                        "partyIdentifiers": {
                                            "partyIds": [{
                                                    "partyIdType": "BIC",
                                                    "partyId": ordinstitution
                                                },
                                                ...[orderinginstitutionlei && {
                                                    "partyIdtype": 'LEI',
                                                    'partyId': orderinginstitutionlei
                                                }]
                                            ]
                                        }
                                    }
                                }]
                            },
                            "accountsInvolved": {
                                "tradeAccountDetails": [{
                                    "accountRoleType": "53B",
                                    "accountDetails": {
                                        "accountId": debitaccnum
                                    }
                                }]
                            },
                            "cashTrade": {
                                "transactionType": "PAYM",
                                "transactionSubType": "CTRF"
