                   addPartyRoleDetailsLEI("52A", "LEI", orderinginstitutionlei);
               } */
            // Add intermediary bank details if both intermediarybank and intermediaryaccnum exist
            if (intermediarybanktype == 'BIC Code') {
                addPartyRoleDetails("56A", "BIC", intermediarybankcode, intermediarybanklei);
                if (intermediaryaccnum) {
                    addAccountDetails('56A', intermediaryaccnum);
                }
                /*  if (intermediarybanklei) {
                      addPartyRoleDetailsLEI("56A", "LEI", intermediarybanklei);
                  } */
            } else if (intermediarybanktype == 'Name and address') {
                addPartyNameDetails("56D", intermediarybank, intermediarybankaddress, intermediarybanklei);
                if (intermediaryaccnum) {
                    addAccountDetails('56D', intermediaryaccnum);
                }
                /*   if (intermediarybanklei) {
                       addPartyRoleDetailsLEI("56D", "LEI", intermediarybanklei);
                   } */
            } else if (intermediarybanktype) {
                //code for local code
                addLocalCodeDetails("56D", intermediarybank, intermediarybankaddress, intermediarybanktype, intermediarybankcode, intermediarybanklei);
                if (intermediaryaccnum) {
                    addAccountDetails('56D', intermediaryaccnum);
