                /*    if (accountwithinstitutionlei) {
                        addPartyRoleDetailsLEI("57D", "LEI", accountwithinstitutionlei);
                    } */
            }

            if (creditacctype == 'BIC Code') {
                addAccountDetails('59A', creditaccnum);
                addPartyRoleDetails("59A", "BIC", creditaccbic, creditaccountlei);
                /*   if (creditaccountlei) {
                       addPartyRoleDetailsLEI("59A", "LEI", creditaccountlei);
                   } */
            } else if (creditacctype == 'Name and address') {
                addAccountDetails('59', creditaccnum);
                addPartyNameDetails("59", creditaccname, creditaccaddress, creditaccountlei);
                /*  if (creditaccountlei) {
                      addPartyRoleDetailsLEI("59", "LEI", creditaccountlei);
                  } */
            }

            if (orderingcustomertype == 'BIC Code') {
                addPartyRoleDetails("50A", "BIC", ordcustomer, orderingcustomerlei);
                /*    if (orderingcustomerlei) {
                         addPartyRoleDetailsLEI("50A", "LEI", orderingcustomerlei);
                    } */
            } else if (orderingcustomertype == 'Name and address') {
                addAccountDetails('50K', ordcustomer);
                addPartyNameDetails("50K", orderingcustomername, orderingcustomeraddress, orderingcustomerlei);
                /*   if (orderingcustomerlei) {
                       addPartyRoleDetailsLEI("50K", "LEI", orderingcustomerlei);
                   } */
            }

