                    "commentType": "70",
                    "comment": this.getFormattedAddress('', remittanceinfo)
                });
            }

            if (charges) {
                body.wrapper.transactions.trade.tradeComments.comments.push({
                    "commentType": "71A",
                    "comment": charges
                });
            }

            if (purposepayment) {
                body.wrapper.transactions.trade.tradeComments.comments.push({
                    "commentType": "72",
                    "comment": "/REC/" + purposepayment
                });
            }
            var a = JSON.stringify(body);

            return a.replaceAll(',""', "");

        } catch (ex) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils:cashPaymentsMT103 - Exception occurred: ' + ex.message);
        }
        // function to add optional partyRoleDetails
        function addPartyRoleDetails(roleType, partyIdType, partyId, lei) {
            body.wrapper.transactions.trade.partiesInvolved.partyRoleDetails.push({
                "partyRoleType": roleType,
                "partyDetails": {
                    "partyIdentifiers": {
                        "partyIds": [{
                                "partyIdType": partyIdType,
                                "partyId": partyId
                            },
                            ...[lei && {
