    getFormattedSenderReceiver: function(address) {
        //MSSCUSTODY-7790
        if (!address) {
            address = '';
        }
        var finalAddress = (address).trim();
        finalAddress = this.addChar(finalAddress, 30);
        var delimeter = "|";
        var parts = finalAddress.split(delimeter);
        var prefixed = parts.map(part => "/BNF/" + part);
        var result = prefixed.join(delimeter);
        return result;
    },

    tradeSettlementsMT54x: function(source_type, senderbic, instType, senreference, action, prevreference, tradedate, settdate, unitprice, sectype, secidentifier, setr, quantty, secaccount, stampduty, counterparty, counterpartytype, buysellformat, buysell, switchaccount, settamount, pset, exchngname, narrative, nationality, accroletype, partyRoleType, beneownership, currency, sourceDate, stcovalue, rtgsvalue, cpaccount, interestdays, interestamount, pricetype, pricetypeoption, dealamount, brokercommission, localtax, stampcharge, othercharge) {
