                    "currencyDetails": {
                        "currencyCode": currency
                    }
                });
            }
            if (localtax) {
                marketCharges.push({
                    "chargeType": 'LOCL',
                    "chargeAmount": localtax,
                    "currencyDetails": {
                        "currencyCode": currency
                    }
                });
            }
            if (stampcharge) {
                marketCharges.push({
                    "chargeType": 'STAM',
                    "chargeAmount": stampcharge,
                    "currencyDetails": {
                        "currencyCode": currency
                    }
                });
            }
            if (othercharge) {
                marketCharges.push({
                    "chargeType": 'OTHR',
                    "chargeAmount": othercharge,
                    "currencyDetails": {
                        "currencyCode": currency
                    }
                });
            }
            var tradeCurrencyDetail = [];
            if (settamount) {
                tradeCurrencyDetail.push({
                    "currencyRoleType": "SETT",
                    "currencyDetails": {
                        "currencyCode": currency
                    }
                });
            }
            if (interestamount) {
                tradeCurrencyDetail.push({
                    "currencyRoleType": "ACRU",
                    "currencyDetails": {
                        "currencyCode": currency
                    }
                });
            }
            if (pricetypeoption == 'B') {
                tradeCurrencyDetail.push({
                    "currencyRoleType": 'DEAL',
                    "currencyDetails": {
                        "currencyCode": currency
                    }
                });
            }

            var body = {
                "wrapper": {
                    "transactions": {
                        "sourceCreateDate": sourceDate,
                        "sourceName": source_type, //MSSCUSTODY-6746
                        "clientShortName": source_type === 'FAX' ? "NULL" : senderbic.slice(0, 8) + senderbic.slice(9, senderbic.length), //MSSCUSTODY-6746
                        "trade": {
                            "tradeDate": tradedate,
                            "tradeSettlementDate": settdate,
                            ...(settamount && { // Add tradeSettlementAmount block here if settamount exists
                                "tradeSettlementAmount": settamount
                            }),
                            "tradeOrderDetails": {
                                "customerReference": senreference,

                                ...(dealamount && { // Add dealamount block here if exists
                                    "orderTransactionDetails": {
                                        "orderAmountDetail": {
                                            "amountType": 'DEAL',
                                            "amount": dealamount,
                                            "currencyDetails": {
                                                "currencyCode": currency
                                            }
                                        }
                                    }
                                }),
                            },

                            ...(marketCharges.length && {
                                "tradeMarketCharges": {
                                    "marketCharge": marketCharges
                                }
                            }),

                            ...(narrative && { // Add tradeComments block here if narrative exists
                                "tradeComments": {
                                    "comments": {
                                        "commentType": "SPRO",
                                        "comment": this.getFormattedAddress('', narrative)
                                    }
                                }
                            }),

                            "partiesInvolved": {
                                "partyRoleDetails": []
                            },
                            "accountsInvolved": {
                                "tradeAccountDetails": [{
                                    "accountDetails": {
                                        "accountId": secaccount
                                    },
                                    "accountRoleType": "SAFE"
                                }]
                            },

                            ...(tradeCurrencyDetail.length && {
                                "currenciesInvolved": {
                                    "tradeCurrencyDetails": tradeCurrencyDetail
                                }
                            }),

                            "instrumentsInvolved": {
                                "tradeInstrumentDetails": {
                                    "instrumentDetails": {
                                        "instrumentIdentifiers": {
                                            "instrumentIds": {
                                                "instrumentIdType": sectype,
                                                "instrumentId": secidentifier
                                            }
                                        }
                                    }
                                }
                            },
                            "securitiesTrade": {
                                "transactionType": "SETT",
                                "transactionSubType": instType,
                                "quantity": quantty,
                                "pset": pset,
                                ...(rtgsvalue && { // Add tradeComments block here if narrative exists 
                                    "rTGSFlag": rtgsvalue
                                }),
                                ...(pricetype && { // Add tradeComments block here if narrative exists 
                                    "tradePriceType": pricetype
                                }), //8435
                                ...(interestdays && { // Add tradeComments block here if narrative exists
                                    "interestAccruedDays": interestdays
                                }),
                                ...(interestamount && { // Add tradeComments block here if narrative exists
                                    "accruedInterestAmount": interestamount
                                }),
                                ...(unitprice && { // Add unitprice block here if exists
                                    "tradeUnitPrice": unitprice
                                }),
                            },

                            "tradeInstructions": {
                                "tradeInstruction": {
                                    "instructionType": action
                                }
                            },
                            ...(prevreference && { //Add tradeReferences block here if prevreference exists
                                "tradeReferences": {
                                    "tradeReference": {
                                        "referenceType": "PREV",
                                        "referenceValue": prevreference
                                    }
                                }
                            }),
                            ...(exchngname && { //Add tradeLocations block here if exchngname exists
                                "tradeLocations": {
                                    "tradeLocation": [{
                                        "locationRoleType": "TRAD",
                                        "locationType": "EXCH",
                                        "locationValue": exchngname
                                    }]
                                }
                            }),
                            "tradeTransactionConditions": {
                                "tradeTransactionCondition": [{
                                    "conditionType": "SETR",
                                    "conditionValue": setr
                                }]
                            }
                        }
                    }
                }
            };


            // Add tradeTransactionConditions if stampduty exists
            if (stampduty && stampduty.trim() !== "")
                addTransactionCondition("STAM", stampduty);

            // Add tradeTransactionConditions if beneficiary exists
            if (beneownership)
                addTransactionCondition("BENE", beneownership);

            if (stcovalue)
                addTransactionCondition("STCO", stcovalue);

            // Add switchaccount if it exists
            if (switchaccount) {
                body.wrapper.transactions.trade.accountsInvolved.tradeAccountDetails.push({
                    "accountDetails": {
                        "accountId": switchaccount,
                        "accountType": "SAFE"
                    },
                    "accountRoleType": accroletype
                });
            }


            if (cpaccount) {
                body.wrapper.transactions.trade.accountsInvolved.tradeAccountDetails.push({
                    "accountDetails": {
                        "accountId": cpaccount,
                        "accountType": "SAFE"
                    },
                    "accountRoleType": partyRoleType
                });
            }
            //Add nationality if it exists
            if (nationality) {
                body.wrapper.transactions.trade.partiesInvolved.partyRoleDetails.push({
                    "partyRoleType": "INVE",
                    "partyDetails": {
                        "partyType": "OTHRPRTY",
                        "partyAddress": nationality
                    },
                });
            }

            // Add counterparty details based on counterpartytype
            switch (counterpartytype) {
                case 'P':
                    addPartyRoleDetails(partyRoleType, "BIC", counterparty);
                    break;
                case 'Q':
                    addPartyRoleDetails(partyRoleType, "partyName", counterparty);
                    break;
                default:
                    addPartyRoleDetails(partyRoleType, counterpartytype.substring(0, counterpartytype.indexOf('|')), counterparty);
                    break; //8387

            }

            // Add buyer/seller details based on buysellformat
            switch (buysellformat) {
                case 'P':
                    addPartyRoleDetails(accroletype, "BIC", buysell);
                    break;
                case 'Q':
                    addPartyRoleDetails(accroletype, "partyName", buysell);
                    break;
                default:
                    addPartyRoleDetails(accroletype, buysellformat.substring(0, buysellformat.indexOf('|')), buysell); //8387
                    break;

            }

            return JSON.stringify(body);
        } catch (ex) {
            gs.info('Script Include - MSS_Unstructured_Instruction_Utils:tradeSettlementsMT54x - Exception occurred: ' + ex.message);
        }

        // function to add tradetransactionconditions
        function addTransactionCondition(conditionType, conditionValue) {
            const transactioncond = {
                "conditionType": conditionType,
                "conditionValue": conditionValue
            };
            body.wrapper.transactions.trade.tradeTransactionConditions.tradeTransactionCondition.push(transactioncond);
        }

        function addTransactionTypeCondition(conditionType, conditionValue) {
            const transactioncond = {
                "conditionType": conditionType,
                "conditionSubType": conditionValue
            };
            body.wrapper.transactions.trade.tradeTransactionConditions.tradeTransactionCondition.push(transactioncond);
        }

        //function to add partyRoleDetails
        function addPartyRoleDetails(roleType, partyIdType, partyId) {
            const partyDetails = {
                "partyRoleType": roleType,
                "partyDetails": {
                    "partyType": "SETPRTY"
                }
            };

            // Dynamically add partyIdType or partyName
            if (partyIdType === "partyName") { //8387
                partyDetails.partyDetails.partyName = partyId; //8387
            } else {
                const partyIdentifier = {
                    "partyIds": {
                        "partyIdType": partyIdType,
                        "partyId": partyId
                    }
                };
                partyDetails.partyDetails.partyIdentifiers = partyIdentifier;
            }

            body.wrapper.transactions.trade.partiesInvolved.partyRoleDetails.push(partyDetails);
        }
    },


    //MSSCUSTODY-5529
    canAssignToMe: function(state, assignedTo, assignmentGroup) {
        //This is called from the UI Action 'Assign to Me' on the Instruction Case Task table.  Requirement is to only allow this button to be displayed if the user is a member of the group that the task is assigned to

        if (state != 3 && assignedTo != gs.getUserID() && gs.getUser().isMemberOf(assignmentGroup)) {
            return true;
        } else {
            return false;
        }

    },

    //MSSCUSTODY-7169 - deactivate Restricted Ccy Instructions
    deactivateMT599Instructions: function(caseId) {
        var grInstructionTask = new GlideRecord('x_hsb11_mss_unst_0_instructions_case_task');
        grInstructionTask.addEncodedQuery('task_type=Instruction^instruction_case=' + caseId);
        grInstructionTask.addQuery('restrictedccy', 'true');
        grInstructionTask.addActiveQuery(); // MSSCUSTODY-7844
        grInstructionTask.query();
        while (grInstructionTask.next()) {
            grInstructionTask.setValue('state', 3);
            grInstructionTask.update();
        }
    },

    //MSSCUSTODY-8462
    deactivateCANCInstructions: function(caseId) {
        var grInstructionTask = new GlideRecord('x_hsb11_mss_unst_0_instructions_case_task');
        grInstructionTask.addEncodedQuery('task_type=Instruction^instruction_case=' + caseId);
        grInstructionTask.addQuery('outputmessagetype', 'CANC');
        grInstructionTask.addActiveQuery(); // MSSCUSTODY-7844
        grInstructionTask.query();
        while (grInstructionTask.next()) {
            grInstructionTask.setValue('state', 3);
            grInstructionTask.update();
        }
    },

    //*MSSCUSTODY-8462 ends

    //MSSCUSTODY-5738 - Auto Unlock the tasks if not updated for more than 10 mins
    checkUpdate: function(sysID) {
        var gdt = new GlideDateTime();
        var task = new GlideRecordSecure('x_hsb11_mss_unst_0_instructions_case_task');
        task.get(sysID);
        task.addActiveQuery();
        task.query();
        if (task.next()) {
            var dur = gdt.getNumericValue() - new GlideDateTime(task.sys_updated_on).getNumericValue();
            if (dur > 720000) {
                task.assigned_to = "";
                task.state = 1;
                task.update();
            }
        }
    },


    type: 'MSS_Unstructured_Instruction_Utils'
};
